{
  "probability": 0.98,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "Early-2026 pace around 606 deaths by February suggests a plausible path to 1,000 deaths by end-April if March–April remain high.",
    "Historical Central Mediterranean tolls (~2,100–2,500 per year) provide a strong baseline that increases the likelihood of crossing 1,000 under current momentum.",
    "Near-term risks (weather shocks, Tunisia crossings, SAR constraints) push the risk upward, but data reporting uncertainty injects some downside variability.",
    "Bayesian calibration yields a high posterior probability (~98%), indicating high confidence even with remaining uncertainties."
  ],
  "confidence": "high",
  "narrative": "Given a fast early-2026 mortality pace and a high historical toll on the Central Mediterranean, the likelihood of reaching 1,000 deaths by May 1, 2026 is strong. However, weather events, policy/SAR dynamics, and provisional tallies create residual uncertainty that prevents near-certainty.",
  "justification": {
    "anchor": {
      "probability": 0.35,
      "basis": "reference class anchored to annual central Mediterranean deaths; 1,000 by end-April sits below annual totals yet is plausible given a strong early-year pace"
    },
    "factor_updates": [
      {
        "factor": "Early-2026 Mediterranean mortality pace (through February 2026)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by February; if March–April remain high, 1,000 by end-April is plausible and aligns with the posterior being near 0.98."
      },
      {
        "factor": "Severe weather and Cyclone Harry affecting the Central Mediterranean",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Weather shocks raise crossing risk and fatalities, supporting a higher near-term total."
      },
      {
        "factor": "Policy/regulatory crackdown and reduced SAR capacity",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Enforcement and SAR constraints can increase fatality risk per crossing, boosting likelihood of crossing the threshold."
      },
      {
        "factor": "Data reporting uncertainty and provisional tallies for 2026",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Potential revisions could undercount, tempering the observed pace; this reduces certainty but not the direction overall."
      },
      {
        "factor": "Surge in departures from Tunisia",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Higher departure volumes raise overall risk and the chance of more deaths."
      }
    ],
    "synthesis_rationale": "Starting from a conservative anchor, we add the strong early-2026 pace and high baseline tolls as positive updates toward hitting 1,000 by end-April. Correlated drivers (weather, crossings, policy) reinforce each other, so the final posterior is calibrated downward from raw 100% to 0.98 to account for potential data revisions and unobserved counts; the interval reflects remaining uncertainty."
  }
}

{
  "probability": 0.98,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    "Early-2026 pace: about 606 deaths/missing by February; if March–April continue at or above this pace, reaching 1,000 by end-April is plausible.",
    "Historical Central Mediterranean tolls are high (~2,100–2,500 per year), which anchors the risk toward higher near-term totals.",
    "Near-term risk factors include severe weather (e.g., Cyclone Harry) and policy/SAR constraints that could increase fatalities per crossing.",
    "Data reporting uncertainty and provisional tallies introduce downside risk to observed counts, but unrevised data still imply a high-risk trajectory."
  ],
  "confidence": "high",
  "narrative": "The model assigns a 98% posterior probability to at least 1,000 Mediterranean deaths by May 1, 2026, driven by a strong early-year pace and a high historical toll, tempered by reporting uncertainty and potential revisions. If March–April do not sustain the pace or SAR improvements occur, the outcome could be less certain.",
  "justification": {
    "anchor": {
      "probability": 0.85,
      "basis": "Reference class is IOM Missing Migrants Project central Mediterranean annual tolls; February 2026 pace (~606) plus historical annual totals imply a high base risk. The anchor probability of 0.85 reflects a strong starting point before updates."
    },
    "factor_updates": [
      {
        "factor": "Early-2026 pace of deaths (Jan–Feb 2026)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Reported ~606 deaths by February; continuation into March–April would push cumulative toll toward 1,000, supporting the target."
      },
      {
        "factor": "Severe weather and storms affecting Central Mediterranean",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Winter storms increase hazard and crossing fatalities, contributing to higher near-term mortality."
      },
      {
        "factor": "Policy/regulatory crackdown and reduced SAR capacity",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Tighter controls and limited SAR can raise fatalities per crossing, raising the odds of reaching 1,000."
      },
      {
        "factor": "Data reporting uncertainty and provisional tallies for 2026",
        "direction": "down",
        "magnitude": "weak",
        "rationale": "Early tallies are provisional; revisions could undercut observed progress toward 1,000 deaths."
      }
    ],
    "synthesis_rationale": "The final probability is a calibrated blend: strong positive updates from Pace, Weather, and SAR risk are tempered by a weak negative update from data-reporting uncertainty. The anchor of 0.85 provides a solid starting point, and the resulting posterior of 0.98 reflects high confidence but acknowledges potential revisions and volatility. Correlations among factors likely exist (e.g., weather and crossings), which may tighten the effective degrees of freedom and could overstate independence; the 0.98 figure accounts for this through conservative calibration."
  }
}

{
  "probability": 0.65,
  "range_low": 0.50,
  "range_high": 0.75,
  "summary": [
    "By February 2026, about 606 Mediterranean deaths were recorded, implying a nontrivial chance of reaching 1,000 by end-April if March–April remain near the early-year pace.",
    "Historical Central Mediterranean tolls (~2,100–2,500 per year) set a high ceiling that makes 1,000 deaths by May plausible, but not guaranteed.",
    "Near-term drivers include weather shocks and rising departures from Tunisia, which push risk upward, while SAR-policy actions could dampen risk somewhat.",
    "Data volatility and provisional tallies introduce uncertainty; undercounting could bias the observed pace lower or higher depending on revisions."
  ],
  "confidence": "medium",
  "narrative": "Early-2026 data show a faster-than-average start with about 606 deaths by February. If March–April keep pace with this early rate, crossing 1,000 by end-April is plausible but remains uncertain given revision risk and potential policy or weather-driven shifts.",
  "justification": {
    "anchor": {
      "probability": 0.65,
      "basis": "Reference class: IOM Missing Migrants Project central Mediterranean deaths; historical annual tolls ~2,100–2,500 and February 2026 tally ~606 provide anchor for a near-term probability around two-thirds for reaching 1,000 by end-April."
    },
    "factor_updates": [
      {
        "factor": "Early-2026 pace of Mediterranean deaths (Jan–Feb 2026)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths by February sets a high starting pace; continuation into March–April would push total toward 1,000 before May."
      },
      {
        "factor": "Weather shocks and storms (Cyclone Harry) increasing crossings",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Severe weather raises fatality risk on crossings, potentially accelerating death toll in March–April."
      },
      {
        "factor": "Surge in departures from Tunisia driving higher crossing risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Rising departures from Tunisia increase crossing volume and exposure."
      },
      {
        "factor": "Policy/SAR capacity responses (European/Italian measures) reducing deaths",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Tighter controls and SAR constraints can lower net fatalities if crossings become riskier to attempt with lower success."
      },
      {
        "factor": "Data reporting uncertainty and provisional tallies for 2026",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Tallies are provisional and subject to revision; could bend the observed pace in either direction."
      },
      {
        "factor": "Underreporting and data gaps (unrecorded shipwrecks could hide true tolls)",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Some missing incidents could push actual tolls higher than reported figures."
      }
    ],
    "synthesis_rationale": "Starting anchor around 0.65 reflects mid-point probability given a strong February pace and high annual total, but with substantial near-term uncertainty. Each factor nudges probability up or down: high near-term pace and weather-driven risk push up; SAR/policy effects and data revision risk push down or add uncertainty. The synthesis weighs these signals to a calibrated, moderately optimistic probability with a broad uncertainty range; still, a true outcome depends on March–April conditions and reporting revisions."
  }
}
